import gzip,csv
rows={}
for l in gzip.open('studies/data/raw/paper_2_GSE21618_series_matrix.txt.gz','rt'):
    if l.startswith('!series_matrix_table_begin'): break
    if l.startswith('!Sample'):
        p=next(csv.reader([l.strip()],delimiter='\t'))
        rows.setdefault(p[0],[]).append(p[1:])
