for k in keys: print(k,len(rows[k]), [len(set(v)) for v in rows[k]])
n=len(rows['!Sample_title'][0])
for i in range(n):
    t=rows['!Sample_title'][0][i]
    if '0h' in t.replace('10h','') and not any(x in t for x in ['10h']) or 'Control' in t:
        print(t,'|',rows['!Sample_source_name_ch1'][0][i],'|',[c[i] for c in rows['!Sample_characteristics_ch1']],'|',rows.get('!Sample_treatment_protocol_ch1',[[None]*n])[0][i][:200])

